package dev.pedro.learning.ecommerce.payment.api;import dev.pedro.learning.ecommerce.payment.domain.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;public record PaymentResponse(UUID id,UUID orderId,BigDecimal amount,PaymentStatus status,String providerReference,String failureReason,Instant createdAt){public static PaymentResponse from(PaymentEntity p){return new PaymentResponse(p.id,p.orderId,p.amount,p.status,p.providerReference,p.failureReason,p.createdAt);}}